def parse_amount(text: str) -> int:
    # Remove all non-numeric characters and 'm' or 'k' suffixes
    cleaned_text = ''.join(filter(str.isdigit, text.replace('m', '').replace('k', '')))
    # Convert the cleaned text to an integer
    if 'm' in text:
        return int(cleaned_text) * 1000000
    elif 'k' in text:
        return int(cleaned_text) * 1000
    else:
        return int(cleaned_text)
