def parse_amount(text: str) -> int:
    # Remove all non-numeric characters and 'm' or 'k' suffixes
    cleaned_text = ''.join(filter(str.isdigit, text.replace('m', '').replace('k', '')))
    # Convert the cleaned text to a float
    num = float(cleaned_text)
    # Remove the decimal part if it exists
    if num.is_integer():
        num = int(num)
    # Convert the number to an integer
    if 'm' in text:
        return int(num) * 1000000
    elif 'k' in text:
        return int(num) * 1000
